        <div className='text-muted-foreground/50 text-[10px]'>
          {!dynamicSummary.isTaskUsage && `/ ${tokenUnitLabel} tokens`}
          {dynamicSummary.isTaskUsage && dynamicSummary.tier?.label}
          {dynamicSummary.tierCount > 1 &&
            ` · ${t('{{count}} tiers', {
              count: dynamicSummary.tierCount,
            })}`}
        </div>
      </div>
    )
  }

  if (isUnconfiguredTaskUsageModel(model)) {
    return (
      <div className='max-w-full min-w-0'>
        <div className='text-sm font-medium'>{t('Not configured')}</div>
        <div className='text-muted-foreground/50 text-[10px]'>
          {t('Usage-based billing')}
        </div>
      </div>
    )
  }

  const isTokenBased = isTokenBasedModel(model)

  if (isTokenBased) {
    const inputPrice = stripTrailingZeros(
      formatPrice(
        model,
        'input',
        tokenUnit,
        showRechargePrice,
        priceRate,
        usdExchangeRate,
        selectedGroup
      )
    )
    const outputPrice = stripTrailingZeros(
      formatPrice(
        model,
        'output',
        tokenUnit,
        showRechargePrice,
        priceRate,
        usdExchangeRate,
        selectedGroup
      )
    )

    return (
      <div className='max-w-full min-w-0'>
        <span className='font-mono text-sm tabular-nums'>
          {inputPrice}
          <span className='text-muted-foreground/40 mx-1'>/</span>
