    formatRequestPrice(
      model,
      showRechargePrice,
      priceRate,
      usdExchangeRate,
      selectedGroup
    )
  )

  return (
    <div className='max-w-full min-w-0'>
      <span className='font-mono text-sm tabular-nums'>{price}</span>
      <div className='text-muted-foreground/50 text-[10px]'>
        / {t('request')}
      </div>
    </div>
  )
},

